import React from 'react';
import '../styles/header.css';

function Header() {
  return (
    <header className="header">
      <div className="header-wrapper">
        <h1 className="logo">판다마켓</h1>
        <button className="login-button">로그인</button>
      </div>
    </header>
  );
}

export default Header;
